/**
 * DEMO DATA. Bergen Car Company platform reviews for the client walkthrough.
 *
 * Every review inserted from this file is tagged three ways so the companion
 * teardown script (`remove-bergen-demo-reviews.ts`) can delete ONLY these rows
 * and nothing else:
 *   1. dealer slug === DEMO_DEALER_SLUG
 *   2. Review.ipAddress === DEMO_MARKER
 *   3. Review.email ends with DEMO_EMAIL_DOMAIN
 *
 * Nothing here touches other dealers, other reviews, ratings config, or schema.
 */

export const DEMO_DEALER_SLUG = "bergen-car";

/** Written into Review.ipAddress on every seeded row. Not a real IP. */
export const DEMO_MARKER = "DEMO_SEED_BERGEN_REVIEWS_2026";

/** Every seeded review email ends with this. `.invalid` is reserved + undeliverable. */
export const DEMO_EMAIL_DOMAIN = "@bergen-demo-reviews.invalid";

export interface DemoReview {
  name: string;
  title: string;
  comment: string;
  visitType: "Purchased New Car" | "Purchased Used Car" | "Service Visit" | "Just Looking";
}

